'use client';
import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { Brand, type BrandName } from '../lib/brands';
import { Seg, Swap, SwapIcon, Tip, useGrow, useReflow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './memory-panel.css';

/** A group of memories, with its own filter tab and colour */
export interface MemoryKind {
  value: string;
  /** Its tab, and the word under each of its memories, like "Brand" */
  label: string;
  /** Its colour, for that word, like 'var(--dm-pl)'. Pick one that reads as text, 4.5:1 on your surface */
  color: string;
}

/** Something the agent remembers */
export interface MemoryItem {
  id: string | number;
  /** Which kind it is, by value */
  kind: string;
  /** What it remembers, like "Headlines stay under eight words" */
  text: string;
  /** Where it came from, like "A thread in #design-system, Sep 4" */
  source?: string;
  /** The app it came from, shown as its own mark, like 'slack' or 'figma' */
  brand?: BrandName;
  /** An icon for where it came from when that isn't an app, like 'comment' for something said in chat. Used without a `brand` */
  icon?: IconName;
  /** Marks it as just learned, with a New tag */
  isNew?: boolean;
  /** Still being learned: the text shimmers, a spinner stands in for its source, and it can't be edited yet */
  learning?: boolean;
  /** Used in the answer the agent is writing: it pulses once when this turns on, and keeps a Used tag */
  used?: boolean;
}

/** The line at the foot of the panel */
export interface MemoryActivity {
  /** Like "Drafting the launch email in Gmail" or "Used in 14 answers this week" */
  text: string;
  /** Shimmers the text, while the agent is at work */
  live?: boolean;
  brand?: BrandName;
  icon?: IconName;
}

export interface MemoryPanelProps {
  /** Like "Team memory" */
  title?: ReactNode;
  icon?: IconName;
  kinds: MemoryKind[];
  /** Every memory, newest first. Leave it out to let Edit and Forget keep their own list */
  memories?: MemoryItem[];
  defaultMemories?: MemoryItem[];
  onMemoriesChange?: (memories: MemoryItem[]) => void;
  /** The tab that is showing: 'all' or a kind's value */
  filter?: string;
  defaultFilter?: string;
  onFilterChange?: (filter: string) => void;
  /** The first tab */
  allLabel?: string;
  /** The line at the foot, like what the agent is answering with its memory now */
  activity?: MemoryActivity;
  /** The source an edited memory gets */
  editedSource?: string;
  /** The tag on a memory marked `isNew` */
  newLabel?: string;
  /** The tag on a memory marked `used` */
  usedLabel?: string;
  /** Called with the memory after an edit */
  onEdit?: (memory: MemoryItem) => void;
  /** Called when a memory is forgotten. It can still come back with Undo for `undoFor` ms */
  onForget?: (memory: MemoryItem) => void;
  /** Called when Undo brings a forgotten memory back */
  onRestore?: (memory: MemoryItem) => void;
  /** How long Undo stays, in ms */
  undoFor?: number;
  /** Draws its own container (the default, as on designme.dev). Set true to sit it flat in a chat thread */
  bare?: boolean;
  className?: string;
}

interface Gone { m: MemoryItem; at: number; leaving: boolean }

const Mark = ({ brand, icon }: { brand?: BrandName; icon?: IconName }) => brand ? <Brand name={brand} /> : icon ? <Icon name={icon} size="xs" /> : null;

/** What the agent remembers about the team, filtered by kind, each memory with the app or place it came from, editable in
    place or forgotten with an undo. New memories arrive with a New tag, and the ones an answer uses pulse. The panel grows and
    shrinks with its list, eased. */
export function MemoryPanel({
  title = 'Team memory', icon = 'book', kinds, memories, defaultMemories = [], onMemoriesChange, filter, defaultFilter = 'all', onFilterChange,
  allLabel = 'All', activity, editedSource = 'Edited by you, just now', newLabel = 'New', usedLabel = 'Used',
  onEdit, onForget, onRestore, undoFor = 4000, bare = false, className
}: MemoryPanelProps) {
  // Clean's one hover glides from memory to memory
  const listRef = useRef<HTMLDivElement>(null);
  useHoverGlide(listRef, '.dm-mmx-m');
  const [list, setList] = useControllable(memories, defaultMemories, onMemoriesChange);
  const [f, setF] = useControllable(filter, defaultFilter, onFilterChange);
  const [gone, setGone] = useState<Gone[]>([]);
  const [editing, setEditing] = useState<MemoryItem['id'] | null>(null);
  const timers = useRef(new Map<MemoryItem['id'], ReturnType<typeof setTimeout>>());
  const edit = useRef<HTMLSpanElement>(null);
  const kindOf = (kind: string) => kinds.find(k => k.value === kind);

  // a new tab changes the list: the rows that stay glide to their new places, the ones that go fade where they were, the new
  // ones come in after one another (motion pieces), and any Undo goes away
  const [, setPaint] = useState(0);
  const order = useRef(new Map<MemoryItem['id'], number>());
  const first = useRef(true);
  useIsoLayoutEffect(() => {
    if (first.current) { first.current = false; return; }
    timers.current.forEach(clearTimeout); timers.current.clear();
    order.current.clear(); setGone([]); setPaint(p => p + 1);
  }, [f]);
  useEffect(() => { const t = timers.current; return () => t.forEach(clearTimeout); }, []);

  // editing starts with the caret at the end of the text
  useIsoLayoutEffect(() => {
    const t = edit.current; if (editing === null || !t) return;
    t.focus();
    const s = document.getSelection(); s?.selectAllChildren(t); s?.collapseToEnd();
  }, [editing]);

  // a memory that has just been learned crossfades from its shimmering line to what it remembers, and its source comes in
  const learnt = useRef(new Set<MemoryItem['id']>());
  list.forEach(m => { if (m.learning) learnt.current.add(m.id); });

  const commit = (m: MemoryItem, text: string) => {
    const next: MemoryItem = { ...m, text: text.trim() || m.text, source: editedSource, brand: undefined, icon: 'edit' };
    setEditing(null);
    setList(list.map(x => (x.id === m.id ? next : x)));
    onEdit?.(next);
  };
  const forget = (m: MemoryItem) => {
    const at = list.indexOf(m);
    setList(list.filter(x => x !== m)); onForget?.(m);
    order.current.delete(m.id);
    setGone(g => [...g, { m, at, leaving: false }]);
    timers.current.set(m.id, setTimeout(() => {
      setGone(g => g.map(x => (x.m === m ? { ...x, leaving: true } : x)));
      timers.current.set(m.id, setTimeout(() => { setGone(g => g.filter(x => x.m !== m)); timers.current.delete(m.id); }, 320));
    }, undoFor));
  };
  const restore = (g: Gone) => {
    clearTimeout(timers.current.get(g.m.id)); timers.current.delete(g.m.id);
    setGone(x => x.filter(y => y !== g));
    const next = [...list]; next.splice(Math.min(g.at, next.length), 0, g.m);
    setList(next); onRestore?.(g.m);
  };

  // forgotten memories hold their place with an Undo until it times out
  const rows: ({ m: MemoryItem; g?: undefined } | { g: Gone; m?: undefined })[] = list.map(m => ({ m }));
  for (const g of gone) rows.splice(Math.min(g.at, rows.length), 0, { g });
  const shown = rows.filter(r => f === 'all' || (r.m ?? r.g.m).kind === f);
  // rows that were there when the tab painted stagger in; anything that arrives later comes in on its own
  if (!order.current.size) shown.forEach((r, i) => { if (r.m) order.current.set(r.m.id, i); });
  const delay = (id: MemoryItem['id']) => (order.current.get(id) ?? 0) * 40 + 'ms';
  // a memory the agent learns while the panel is open opens its own height, so the panel grows instead of jumping
  const reduce = useReducedMotion(), grown = useRef(new WeakSet<HTMLElement>());
  const growRow = (el: HTMLDivElement | null) => {
    if (!el || grown.current.has(el)) return; grown.current.add(el);
    if (reduce || !el.animate) return;
    // (Clean fades without a blur)
    const cs = getComputedStyle(el), ease = cs.getPropertyValue('--dm-ease').trim() || 'ease', blur = cs.getPropertyValue('--dm-motion').trim() === 'clean' ? 0 : 4;
    el.animate([{ height: '0px', paddingTop: '0px', paddingBottom: '0px', opacity: 0, filter: `blur(${blur}px)`, overflow: 'hidden' },
      { height: cs.height, paddingTop: cs.paddingTop, paddingBottom: cs.paddingBottom, opacity: 1, filter: 'blur(0px)', overflow: 'hidden' }], { duration: 560, easing: ease });
  };
  // no room is kept for a memory still to come (owner, 17 Nov): the panel grows and shrinks with its list, eased (as grow() on
  // the site)
  const [box, inner] = useGrow();
  useReflow(box, '.dm-mmx-m', { blur: true, enter: false, host: listRef });

  return (
    <div data-dm="" ref={box} className={cx('dm-mmx dm-growing dm-mx-grow dm-mx-ic', !bare && 'dm-panel', className)} style={bare ? { paddingInline: 0 } : undefined}>
      <div ref={inner} className="dm-grow">
      {/* the head names the panel; a count and a row of the sources' marks would repeat what the list shows */}
      <div className="dm-mmx-h">
        <span className="dm-mmx-ic"><Icon name={icon} /></span>
        <b className="dm-mmx-ht">{title}</b>
        <div className="dm-mmx-tab" style={{ display: 'flex' }}>
          <Seg label="Filter" value={f} onChange={setF} options={[{ value: 'all', label: allLabel }, ...kinds.map(k => ({ value: k.value, label: k.label }))]} />
        </div>
      </div>
      <div ref={listRef} className="dm-mmx-list dm-mx-glide">
        {shown.map(r => {
          if (r.g) {
            const { m, leaving } = r.g;
            return (
              <div key={`gone-${m.id}`} className={cx('dm-mmx-gone', leaving ? 'dm-leave' : 'dm-enter')}>
                <span>Forgot “{m.text.slice(0, 32)}{m.text.length > 32 ? '…' : ''}”</span>
                <button type="button" onClick={() => restore(r.g)}>Undo</button>
              </div>
            );
          }
          const m = r.m, arriving = !!(m.isNew || m.learning) && !order.current.has(m.id), k = kindOf(m.kind);
          const fresh = learnt.current.has(m.id) && !m.learning;
          return (
            // a memory that turns `used` pulses once, as the class arrives
            <div key={m.id} data-key={String(m.id)} ref={arriving ? growRow : undefined}
              className={cx('dm-mmx-m', !arriving && 'dm-enter', m.learning && 'dm-learn', m.used && 'dm-use')}
              style={{ '--dm-k': k?.color ?? 'var(--dm-muted)', ...(arriving ? null : { animationDelay: delay(m.id) }) } as CSSProperties}>
              <span key={m.learning ? 'learn' : 'from'} className={cx('dm-mmx-src', fresh && 'dm-enter')} aria-hidden="true">
                {m.learning ? <span className="dm-spin" /> : <Mark brand={m.brand} icon={m.icon} />}
              </span>
              <span className="dm-mmx-b">
                {editing === m.id
                  ? <span key="edit" ref={edit} className="dm-t" spellCheck={false} contentEditable suppressContentEditableWarning
                      onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur(); } }}
                      onBlur={e => commit(m, e.currentTarget.textContent ?? '')}>{m.text}</span>
                  : <Swap key="view" className={cx('dm-t', m.learning && 'dm-shim')}>{m.text}</Swap>}
                <span className="dm-mmx-meta">
                  {k && <span className="dm-k">{k.label}</span>}
                  {k && m.source && <span aria-hidden="true">·</span>}
                  {m.source && <span className="dm-s">{m.source}</span>}
                  {m.isNew && <span className="dm-tag dm-nw">{newLabel}</span>}
                  {m.used && <span className="dm-tag dm-nw">{usedLabel}</span>}
                </span>
              </span>
              <span className="dm-acts">
                <Tip label="Edit"><button type="button" className="dm-ib dm-mx-press" aria-label="Edit" disabled={m.learning} onClick={() => setEditing(m.id)}><Icon name="edit" size="xs" /></button></Tip>
                <Tip label="Forget"><button type="button" className="dm-ib dm-mx-press" aria-label="Forget" disabled={m.learning} onClick={() => forget(m)}><Icon name="trash" size="xs" /></button></Tip>
              </span>
            </div>
          );
        })}
      </div>
      {activity && (
        <div className="dm-mmx-f" aria-live="polite">
          <span className="dm-mmx-fi" aria-hidden="true"><SwapIcon id={activity.brand ?? activity.icon ?? 'spark'}><Mark brand={activity.brand} icon={activity.icon ?? (activity.brand ? undefined : 'spark')} /></SwapIcon></span>
          <Swap className={cx('dm-mmx-ft', activity.live && 'dm-shim')}>{activity.text}</Swap>
        </div>
      )}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Memory panel ---------- */
/* each memory shows where it came from, as that source's own mark (Slack, Figma, GitHub, Notion, Linear, Drive) or an icon
   (something said in chat, an edit), and its kind in the kind's colour (--dm-k). A memory the agent learns arrives with a spinner
   on its mark and its words shimmering while it works the rule out, then a New tag (no tinted band, owner 18 Nov); the
   memories an answer uses pulse once with a quiet grey (never a hue) and say so. The card sits on two columns (owner, 18 Nov),
   its content 16px from every edge: the head's mark in a 28px column with each memory's mark centred under it, and the title,
   each memory and the footer's words 12px after it; a row's hover fill reaches 8px out round its content, and its Edit and
   Forget end on the content's right edge, under the filter. The panel keeps no room for the memory still to come: it grows as
   the new one opens its row (grow()) and stays centred in its stage */
.dm-mmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-2);container:mmx/inline-size}
.dm-mmx-h{display:flex;align-items:center;gap:8px 12px}
.dm-mmx-ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.dm-mmx-ht{flex:1 0 auto;min-width:0;font-size:14px;line-height:20px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-mmx-tab button{font-size:12px;height:26px;padding:0 9px}
/* a narrow panel puts the filter on its own line under the title, from the content's left edge */
@container mmx (max-width:330px){.dm-mmx-h{display:grid;grid-template-columns:28px minmax(0,1fr)}.dm-mmx-tab{grid-column:1/-1;justify-self:start}}
/* a memory's mark sits on the head's tile column and its actions end on the content's 16px edge; its hover fill reaches 8px
   out round it, into the padding, in every style (owner, 26 Nov) */
.dm-mmx-list{display:flex;flex-direction:column;margin:0 calc(-1 * var(--dm-s-2))}
.dm-mmx-m{display:flex;align-items:flex-start;gap:12px;padding:var(--dm-s-2);border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;line-height:1.5;transition:background .3s}
@media (hover:hover) and (pointer:fine){.dm-mmx-m:hover{background:var(--dm-row)}}
/* its motion (the core's motion pieces, owner, 26 Nov): one highlight glides from memory to memory in every style (.mx-glide);
   a filter moves the rows (reflow()); a press on Edit or Forget shows at once (.mx-press); a source's spinner and mark, and the
   footer's mark, crossfade (.mx-ic); the panel grows on the spring (.mx-grow) */
.dm-mmx-src{width:28px;height:28px;margin-top:1px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;background:var(--dm-surface);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.dm-mmx-src .dm-brand{width:15px;height:15px;color:var(--dm-fg)}
.dm-mmx-src .dm-spin{width:12px;height:12px}
.dm-mmx-b{flex:1;min-width:0;display:flex;flex-direction:column}
/* a memory that wraps never leaves one word alone on its last line (owner, 24 Nov) */
.dm-mmx-b .dm-t{text-wrap:pretty}
.dm-mmx-m .dm-t{outline:0;border-radius:var(--dm-r-tiny,5px);padding:0 3px;margin:0 -3px}
.dm-mmx-m .dm-t[contenteditable="true"]{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
.dm-mmx-m .dm-t[contenteditable="true"]:focus{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* under it: its kind in the kind's colour, then where it came from */
.dm-mmx-meta{display:flex;align-items:center;gap:6px;min-width:0;font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.dm-mmx-meta>*{flex:none}
.dm-mmx-meta .dm-k{color:var(--dm-k);font-weight:500}
.dm-mmx-meta .dm-s{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis}
.dm-mmx-meta .dm-tag.dm-nw{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-fg))}
.dm-mmx-m .dm-acts{display:flex;opacity:0;transition:opacity .2s}
.dm-mmx-m:focus-within .dm-acts{opacity:1}
@media (hover:hover) and (pointer:fine){.dm-mmx-m:hover .dm-acts{opacity:1}}
/* Forget's glyph ends on the content's edge, under the filter, its hover circle reaching out round it */
.dm-mmx-m .dm-ib{width:24px;height:24px}
.dm-mmx-m .dm-acts{margin-right:-6px}
.dm-mmx-m.dm-learn .dm-acts{visibility:hidden}
/* a memory an answer uses pulses once with a quiet grey fill, and its source lifts */
.dm-mmx-m.dm-use{animation:dm-mmxuse 1.4s var(--dm-ease)}
.dm-mmx-m.dm-use .dm-mmx-src{animation:dm-mmxlift .6s var(--dm-ease)}
/* (the pulse is an inset shade, not the row's fill, so the gliding hover, which clears the rows' own fills, never hides it) */
@keyframes dm-mmxuse{0%{box-shadow:inset 0 0 0 99px var(--dm-hover)}100%{box-shadow:inset 0 0 0 99px transparent}}
@keyframes dm-mmxlift{40%{transform:translateY(-2px) scale(1.08)}}
/* a forgotten memory leaves a line with its Undo in its place: the words on the memories' mark column, Undo ending where their
   actions end */
.dm-mmx-gone{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:32px;padding:4px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:12.5px;color:var(--dm-muted);background:var(--dm-chip)}
.dm-mmx-gone span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-mmx-gone button{flex:none;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;font-size:12.5px}
/* the line at the foot: how often the memory is used, or the answer it is helping with now; its mark centred in the memories'
   mark column and its words on their words column */
.dm-mmx-f{display:flex;align-items:center;gap:12px;margin-top:var(--dm-s-1);padding:var(--dm-s-4) 0 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;line-height:18px;color:var(--dm-muted)}
.dm-mmx-fi{display:grid;place-items:center;flex:none;width:28px;color:var(--dm-fg2)}
.dm-mmx-fi .dm-brand{width:14px;height:14px}
.dm-mmx-ft{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-mmx-ft.dm-sw{display:block}
:root:not([data-style="soft"],[data-style="clean"]) .dm-mmx-m.dm-use:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:dm-mmxusebp .9s steps(3,end)}
@keyframes dm-mmxusebp{0%{box-shadow:inset 0 0 0 99px var(--dm-hover)}100%{box-shadow:inset 0 0 0 99px transparent}}
:root:not([data-style="soft"],[data-style="clean"]) .dm-mmx-m.dm-use .dm-mmx-src:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:dm-mmxbp .9s steps(1,end)}
@keyframes dm-mmxbp{0%,50%{box-shadow:inset 0 0 0 1px var(--dm-line-strong)}51%,100%{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-mmx :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-mmx .dm-ib:active,:root [data-style="clean"] .dm-mmx .dm-ib:active,:root [data-style="clean"].dm-mmx .dm-ib:active{transform:none}
/* Clean (owner, 18 Nov): the head's mark is the neutral tile with a hairline that the sources' marks have; the rows' fills are
   concentric with the card (14px, 8px in); an edited memory is a field with Clean's 10px corners; the footer is an off-white foot
   strip, edge to edge, its mark and words on the card's columns */
:root[data-style="clean"] .dm-mmx-ic,:root [data-style="clean"] .dm-mmx-ic,:root [data-style="clean"].dm-mmx-ic{color:var(--dm-fg2);background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-mmx-src,:root [data-style="clean"] .dm-mmx-src,:root [data-style="clean"].dm-mmx-src{box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] :is(.dm-mmx-m,.dm-mmx-gone),:root [data-style="clean"] :is(.dm-mmx-m,.dm-mmx-gone),:root [data-style="clean"]:is(.dm-mmx-m,.dm-mmx-gone){border-radius:calc(var(--dm-r-card) - 8px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-mmx-m .dm-t[contenteditable="true"],:root [data-style="clean"] .dm-mmx-m .dm-t[contenteditable="true"],:root [data-style="clean"].dm-mmx-m .dm-t[contenteditable="true"]{padding:1px 6px;margin:-1px -6px;border-radius:var(--dm-r-field)}
:root[data-style="clean"] .dm-mmx-m .dm-acts,:root [data-style="clean"] .dm-mmx-m .dm-acts,:root [data-style="clean"].dm-mmx-m .dm-acts{transition:opacity var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-mmx-f,:root [data-style="clean"] .dm-mmx-f,:root [data-style="clean"].dm-mmx-f{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:var(--dm-s-1) calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4));padding:0 var(--dm-s-4);background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-mmx-m.dm-use,:root [data-style="clean"] .dm-mmx-m.dm-use,:root [data-style="clean"].dm-mmx-m.dm-use{animation:dm-mmxuse 1.4s var(--dm-ease)}
